from itertools import permutations

# Use constraint programming with python-constraint or brute force with pruning
# Let's try with pysat or a custom backtracking solver

def check_graceful(labels, edges):
    """Check if a labeling is graceful"""
    n_edges = len(edges)
    edge_labels = set()
    for u, v in edges:
        diff = abs(labels[u] - labels[v])
        if diff == 0 or diff > n_edges:
            return False
        if diff in edge_labels:
            return False
        edge_labels.add(diff)
    return len(edge_labels) == n_edges

# Try with backtracking
def solve_graceful():
    n_vertices = 10
    n_edges = 13
    edges = []
    for g in range(5):
        edges.append((g*2, g*2+1))
    for g in range(4):
        edges.append((g*2, g*2+2))
        edges.append((g*2+1, g*2+3))

    labels = [None] * n_vertices
    used_labels = set()
    used_edge_labels = set()

    # Build adjacency for incremental checking
    adj = [[] for _ in range(n_vertices)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    def backtrack(vertex):
        if vertex == n_vertices:
            return True

        for label in range(n_edges + 1):
            if label in used_labels:
                continue

            # Check edge labels with already-labeled neighbors
            new_edge_labels = []
            valid = True
            for neighbor in adj[vertex]:
                if labels[neighbor] is not None:
                    diff = abs(label - labels[neighbor])
                    if diff == 0 or diff > n_edges or diff in used_edge_labels or diff in new_edge_labels:
                        valid = False
                        break
                    new_edge_labels.append(diff)

            if valid:
                labels[vertex] = label
                used_labels.add(label)
                for d in new_edge_labels:
                    used_edge_labels.add(d)

                if backtrack(vertex + 1):
                    return True

                labels[vertex] = None
                used_labels.remove(label)
                for d in new_edge_labels:
                    used_edge_labels.remove(d)

        return False

    if backtrack(0):
        return labels
    return None

result = solve_graceful()
print(f"Result: {result}")
if result:
    edges = []
    for g in range(5):
        edges.append((g*2, g*2+1))
    for g in range(4):
        edges.append((g*2, g*2+2))
        edges.append((g*2+1, g*2+3))
    print(f"Valid: {check_graceful(result, edges)}")
    edge_labels = sorted([abs(result[u] - result[v]) for u, v in edges])
    print(f"Edge labels: {edge_labels}")
